exercises.solution:
body { margin: 0; font: 1rem/1.5 sans-serif; }
.tableau {
  --espace: 16px;
  --surface: #f8fafc;
  --texte: #172a3a;
  --ligne: #475569;
  --accent: #164e63;
  display: grid;
  gap: var(--espace);
  padding: var(--espace);
  color: var(--texte);
  background-color: var(--surface);
}
.entete {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--espace);
}
.entete h1 { margin: 0; }
.carte {
  border: 1px solid var(--ligne);
  border-radius: 8px;
  padding: var(--espace);
  background-color: #ffffff;
}
.badge {
  padding: 2px 8px;
  border: 1px solid var(--accent);
  border-radius: 4px;
  color: var(--accent);
}
